MATCH (a {name: 'A'}), (b {name: 'B'})
MERGE (a)-[r:TYPE]->(b)
  ON MATCH SET r += {name: 'baz', name2: 'baz'}

MATCH (a {name: 'A'}), (b {name: 'B'})
MERGE (a)-[r:TYPE]->(b)
ON CREATE SET r += {name: 'bar', name2: 'baz'}

MATCH (n:X {name: 'A'})
SET n += {name: null}
RETURN n

MATCH (n:X {name: 'A'})
SET n = {name: 'B', baz: 'C'}
RETURN n

MATCH (n:X {name: 'A'})
SET n = {name: 'B', name2: null, baz: 'C'}
RETURN n

MATCH (n:X)
SET n = {name: 'A', name2: 'B', num: 5}
RETURN n

OPTIONAL MATCH (a:DoesNotExist)
SET a += {num: 42}
RETURN a

OPTIONAL MATCH (a:DoesNotExist)
SET a = {num: 42}
RETURN a

